{"cmd":"cat > /root/output/js/visualization.js <<'JS'
const chartWidth = 680;
const chartHeight = 620;
const csvPath = "data/stock-descriptions.csv";

const palette = ["#4e79a7", "#f28e2b", "#59a14f", "#e15759", "#76b7b2"];

const svg = d3
  .select("#bubble-chart")
  .append("svg")
  .attr("viewBox", `0 0 ${chartWidth} ${chartHeight}`)
  .attr("width", chartWidth)
  .attr("height", chartHeight)
  .attr("role", "img")
  .attr("aria-label", "Bubble chart of stocks grouped by sector");

const tooltip = d3.select("#tooltip");

function formatMarketCap(value) {
  if (value == null || Number.isNaN(value)) {
    return "—";
  }
  const abs = Math.abs(value);
  if (abs >= 1e12) {
    return `${(value / 1e12).toFixed(2)}T`;
  }
  if (abs >= 1e9) {
    return `${(value / 1e9).toFixed(2)}B`;
  }
  if (abs >= 1e6) {
    return `${(value / 1e6).toFixed(2)}M`;
  }
  return value.toLocaleString("en-US");
}

function clearSelection() {
  d3.selectAll(".node").classed("selected", false);
  d3.selectAll("#stock-table tbody tr").classed("selected", false);
}

function selectTicker(ticker) {
  clearSelection();
  d3.selectAll(`.node[data-ticker='${ticker}']`).classed("selected", true);
  d3.selectAll(`#stock-table tbody tr[data-ticker='${ticker}']`).classed(
    "selected",
    true
  );
}

d3.csv(csvPath, (d) => {
  const rawCap = d.marketCap && d.marketCap.trim() !== "" ? +d.marketCap : null;
  return {
    ticker: d.ticker,
    sector: d.sector,
    name: d["full name"],
    marketCap: Number.isFinite(rawCap) ? rawCap : null,
  };
}).then((data) => {
  const cleanData = data.filter((d) => d.ticker);
  cleanData.sort((a, b) => d3.ascending(a.ticker, b.ticker));

  const sectors = Array.from(new Set(cleanData.map((d) => d.sector))).sort(
    d3.ascending
  );
  const color = d3.scaleOrdinal().domain(sectors).range(palette);

  const capValues = cleanData
    .filter((d) => d.marketCap != null)
    .map((d) => d.marketCap);
  const capExtent = d3.extent(capValues);
  const radiusScale = d3.scaleSqrt().domain(capExtent).range([18, 52]);
  const etfRadius = 20;

  const center = { x: chartWidth / 2, y: chartHeight / 2 };
  const clusterRadiusX = 150;
  const clusterRadiusY = 120;
  const sectorPositions = {};

  sectors.forEach((sector, index) => {
    const angle = (index / sectors.length) * Math.PI * 2 - Math.PI / 2;
    sectorPositions[sector] = {
      x: center.x + Math.cos(angle) * clusterRadiusX,
      y: center.y + Math.sin(angle) * clusterRadiusY,
    };
  });

  cleanData.forEach((d, i) => {
    d.radius = d.marketCap != null ? radiusScale(d.marketCap) : etfRadius;
    const pos = sectorPositions[d.sector];
    const offsetX = (i % 6) * 3;
    const offsetY = Math.floor(i / 6) * 3;
    d.x = pos.x + offsetX;
    d.y = pos.y + offsetY;
  });

  const simulation = d3
    .forceSimulation(cleanData)
    .force(
      "x",
      d3.forceX((d) => sectorPositions[d.sector].x).strength(0.22)
    )
    .force(
      "y",
      d3.forceY((d) => sectorPositions[d.sector].y).strength(0.22)
    )
    .force(
      "collide",
      d3.forceCollide((d) => d.radius + 1).iterations(2)
    )
    .stop();

  for (let i = 0; i < 240; i += 1) {
    simulation.tick();
  }

  svg
    .append("rect")
    .attr("x", 0)
    .attr("y", 0)
    .attr("width", chartWidth)
    .attr("height", chartHeight)
    .attr("fill", "transparent")
    .on("click", () => clearSelection());

  const nodes = svg
    .append("g")
    .attr("class", "nodes")
    .selectAll("g")
    .data(cleanData, (d) => d.ticker)
    .join("g")
    .attr("class", "node")
    .attr("data-ticker", (d) => d.ticker)
    .attr("transform", (d) => `translate(${d.x}, ${d.y})`)
    .on("click", (event, d) => {
      event.stopPropagation();
      selectTicker(d.ticker);
    });

  nodes
    .append("circle")
    .attr("r", (d) => d.radius)
    .attr("fill", (d) => color(d.sector))
    .attr("stroke", "#111827")
    .attr("stroke-width", 1);

  nodes
    .append("text")
    .attr("class", "bubble-label")
    .attr("text-anchor", "middle")
    .attr("dy", "0.35em")
    .attr("font-size", (d) => Math.max(9, Math.min(14, d.radius * 0.55)))
    .text((d) => d.ticker);

  nodes
    .on("mousemove", (event, d) => {
      if (d.marketCap == null || d.sector === "ETF") {
        tooltip.classed("visible", false);
        return;
      }
      tooltip
        .classed("visible", true)
        .html(
          `<div class="tt-title">${d.ticker}</div>` +
            `<div class="tt-name">${d.name}</div>` +
            `<div class="tt-sector">${d.sector}</div>`
        )
        .style("left", `${event.pageX + 14}px`)
        .style("top", `${event.pageY - 24}px`);
    })
    .on("mouseout", () => tooltip.classed("visible", false));

  const legend = svg
    .append("g")
    .attr("class", "legend")
    .attr("transform", `translate(${chartWidth - 170}, 20)`);

  const legendItem = legend
    .selectAll("g")
    .data(sectors)
    .join("g")
    .attr("transform", (d, i) => `translate(0, ${i * 20})`);

  legendItem
    .append("rect")
    .attr("width", 12)
    .attr("height", 12)
    .attr("rx", 3)
    .attr("fill", (d) => color(d));

  legendItem
    .append("text")
    .attr("x", 18)
    .attr("y", 10)
    .text((d) => d);

  const tbody = d3.select("#stock-table tbody");

  const rows = tbody
    .selectAll("tr")
    .data(cleanData, (d) => d.ticker)
    .join("tr")
    .attr("data-ticker", (d) => d.ticker)
    .on("click", (event, d) => {
      event.stopPropagation();
      selectTicker(d.ticker);
    });

  rows.append("td").text((d) => d.ticker);
  rows.append("td").text((d) => d.name);
  rows.append("td").text((d) => d.sector);
  rows
    .append("td")
    .attr("class", "num")
    .text((d) => formatMarketCap(d.marketCap));
});
JS"}
